import json, sys

def deduplicate_webhooks(payload: dict) -> dict:
    ttl = int(payload.get('ttl_seconds', 0))
    last_seen: dict[str, int] = {}
    accepted: list[str] = []
    duplicates = 0
    for ev in payload.get('events', []):
        eid = ev['event_id']
        ts = int(ev['timestamp'])
        if eid not in last_seen or (ts - last_seen[eid]) >= ttl:
            accepted.append(eid)
            last_seen[eid] = ts
        else:
            duplicates += 1
    return {'accepted_ids': accepted, 'duplicate_count': duplicates}

if __name__ == '__main__':
    print(json.dumps(deduplicate_webhooks(json.loads(sys.stdin.read()))))
